def mostrar(v):
    v = round(v, 6)
    if v == int(v):
        return str(int(v))
    return f'{v:.2f}'


def tokens(expr, letras=''):
    lista = [None] * len(expr)
    n = 0
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isdigit():
            num = ''
            while i < len(expr) and expr[i].isdigit():
                num = num + expr[i]
                i = i + 1
            lista[n] = num
            n = n + 1
            continue
        if c in '+-*/^()' or c in letras:
            lista[n] = c
            n = n + 1
        elif c != ' ':
            raise ValueError(f'carácter {c}')
        i = i + 1
    return lista[:n]


def validar(toks):
    espera = True
    abiertos = 0
    for i in range(len(toks)):
        t = toks[i]
        if t.isdigit() or t.isalpha():
            if not espera:
                raise ValueError('falta un operador')
            espera = False
        elif t == '(':
            if not espera:
                raise ValueError('falta un operador')
            abiertos = abiertos + 1
        elif t == ')':
            if abiertos == 0:
                raise ValueError('paréntesis sin abrir')
            if espera:
                raise ValueError('falta un operando')
            abiertos = abiertos - 1
        elif t == '-' and espera:
            toks[i] = '~'
        else:
            if espera:
                raise ValueError('falta un operando')
            espera = True
    if espera:
        raise ValueError('falta un operando')
    if abiertos > 0:
        raise ValueError('paréntesis sin cerrar')
    return toks


JER = {'+': 1, '-': 1, '*': 2, '/': 2, '~': 3, '^': 4}


def le_gana(cima, nuevo):
    if cima == '(' or nuevo == '~':
        return False
    if JER[cima] > JER[nuevo]:
        return True
    return JER[cima] == JER[nuevo] and nuevo != '^'


def a_postfix(toks):
    pila = [None] * len(toks)
    p = 0
    salida = [None] * len(toks)
    n = 0
    for t in toks:
        if t == '(':
            pila[p] = t
            p = p + 1
        elif t == ')':
            while pila[p - 1] != '(':
                p = p - 1
                salida[n] = pila[p]
                n = n + 1
            p = p - 1
        elif t in JER:
            while p > 0 and le_gana(pila[p - 1], t):
                p = p - 1
                salida[n] = pila[p]
                n = n + 1
            pila[p] = t
            p = p + 1
        else:
            salida[n] = t
            n = n + 1
    while p > 0:
        p = p - 1
        salida[n] = pila[p]
        n = n + 1
    return salida[:n]


def operar(a, op, b):
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        return a / b
    return a ** b


def evaluar(post, valores={}):
    pila = [None] * len(post)
    p = 0
    for t in post:
        if t == '~':
            pila[p - 1] = -pila[p - 1]
        elif t in '+-*/^':
            p = p - 1
            b = pila[p]
            a = pila[p - 1]
            pila[p - 1] = operar(a, t, b)
        else:
            pila[p] = valores[t] if t.isalpha() else int(t)
            p = p + 1
    return pila[0]


